CREATE TABLE IF NOT EXISTS search_growth_nonces (nonce TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS search_growth_runs (environment TEXT NOT NULL, client_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, request_id TEXT NOT NULL, correlation_id TEXT NOT NULL, mode TEXT NOT NULL, input_count INTEGER NOT NULL, action_count INTEGER NOT NULL, llm_called INTEGER NOT NULL DEFAULT 0, provider_spend_enabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, PRIMARY KEY(environment, client_id, idempotency_key));
CREATE TABLE IF NOT EXISTS search_growth_actions (environment TEXT NOT NULL, client_id TEXT NOT NULL, dedup_key TEXT NOT NULL, run_id TEXT NOT NULL, action_type TEXT NOT NULL, score INTEGER NOT NULL, confidence TEXT NOT NULL, owner_class TEXT NOT NULL, manual_review_required INTEGER NOT NULL, limitations_json TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, PRIMARY KEY(environment, client_id, dedup_key));
